		name=name,
		model=model,
		model_key=model,
		engine_url=f"https://10.0.0.9/e/{name.lower()}",
		status=status,
		inference_server=server,
		max_num_seqs=max_num_seqs,
		model_deployment=model_deployment,
	)


def deployment(name="qwen3-35b-ap-south-1", max_num_seqs=0, engine_image=None):
